contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public function containing the test logic
    // _caller is the address that will attempt to call setL1BlockValues (msg.sender simulated by calling from test harness)
    // _initialNumber is the value we first set by the depositor; _attemptNumber is the value attempted by _caller
    // The testing harness must arrange txs so that the first call is made from the depositor account and the second from _caller.
    function run(address /*_depositor*/ , address /*_caller*/ , uint64 _initialNumber, uint64 _attemptNumber, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public {
        // Precondition: nothing enforced here; caller/harness must ensure actual msg.sender used for c calls.
        // First call: depositor sets initialNumber. This must be performed by the real depositor externally.
        // The test harness should call this function twice in separate transactions with appropriate msg.sender, but
        // since we cannot control msg.sender here, we express the distinguishing assertion using only public getters.

        // Observe number after the two external calls done by the harness (first by depositor to set _initialNumber,
        // then by an arbitrary caller attempting to set _attemptNumber). The distinguishing property is:
        // after a non-depositor attempts to set values, the stored number must equal the original _initialNumber (P)
        // but under the mutant it would equal _attemptNumber.

        // Read the stored number and assert it equals the initial value (depositor's value)
        uint64 stored = c.number();

        assert(stored == _initialNumber);
    }

    // fallbacks allowed by template
    receive() external payable {}
    fallback() external payable {}
}

